void pfodMainMenu::tickCharts(pfodParser &parser) {
  chart_sendData(parser);
}

void pfodMainMenu::chart_sendData(pfodParser &parser) {
  if (chart_plotDataTimer.justFinished()) {
    chart_plotDataTimer.repeat(); // restart plot data timer, without drift
    chart_readPlotData(); // virtual hook -- assigns the 3 plot vars
    // send plot data in CSV format
    parser.print(millis() - plot_msOffset); // time in milliseconds
    parser.print(','); parser.print(((float)(chart_plot_1_var-chart_plot_1_varMin)) * chart_plot_1_scaling + chart_plot_1_varDisplayMin);
    parser.print(','); parser.print(((float)(chart_plot_2_var-chart_plot_2_varMin)) * chart_plot_2_scaling + chart_plot_2_varDisplayMin);
    parser.print(','); parser.print(((float)(chart_plot_3_var-chart_plot_3_varMin)) * chart_plot_3_scaling + chart_plot_3_varDisplayMin);
    parser.println(); // end of CSV data record
  }
}

float getPlotVarScaling(long varMax, long varMin, float displayMax, float displayMin) {
  long varRange = varMax - varMin;
  if (varRange == 0) { varRange = 1; } // prevent divide by zero
  return (displayMax - displayMin)/((float)varRange);
}

void pfodMainMenu::sendMainMenu(pfodParser& parser) {
  // !! Remember to change the parser version string OR Clear the cache
  //    every time you edit this method
  parser.menu();  // start a Menu screen pfod message.  Send {,
  // send menu background, format, prompt, refresh and version
  parser.print(F("<bg n><+4><b>~")); // background n, +4 size, bold
  parser.print(mainMenuPromptText_var); // output the current prompt text
  parser.sendRefreshAndVersion(refresh_ms); // send the menu version 
  // send menu items
  parser.onOffDisplay(sliderDisplay_Cmd); // start Data Display (outputs |!cmd)
  parser.print(F("<bg n>")); // background n
  parser.print('`');
  parser.print(sliderDisplay_var); // output the current value
  parser.print(F("~A0 ~V`1023`0~5.0~0~"));
  parser.label(label_Cmd); // start Label
  parser.print(F("<bg n><-6>")); // background n, -6 size
  parser.print(F("~"));
  parser.print(label_var); // output the current text
  parser.onOffDisplay(onOffIn_Cmd); // start On/Off Display (outputs |!cmd)
  parser.print(F("<bg n><+4><b>")); // background n, +4 size, bold
  parser.print('`');
  parser.print(onOffIn_var); // output the current state 0 Closed or 1 Open
  parser.print(F("~Door is ~~Closed\\Open~t"));
  // Note the \\\\ inside the ' 's to send \\ ...
  parser.label(label_2_Cmd); // start Label
  parser.print(F("<bg n><-6>")); // background n, -6 size
  parser.print(F("~"));
  parser.print(label_2_var); // output the current text
  parser.slider(sliderIO_Cmd); // start Slider
  parser.print(F("<bg n>")); // background n
  parser.print('`');
  parser.print(sliderIO_var); // output the current value 
  parser.print(F("~PWM Setting ~%`255`0~100~0~"));
  parser.slider(onOffOut_Cmd); // start Slider
  parser.print(F("<bg t><+6><b>")); // background t, +6 size, bold
  parser.print('`');
  parser.print(onOffOut_var); // output the current value 
  parser.print(F("~LED is ~~Off\n\\On\n<-3>Turns off after 10sec~t"));
  // Note the \\\\ inside the ' 's to send \\ ...
  parser.button(chart_Cmd); // start Button (opens chart)
  parser.print(F("<bg n><+4>")); // background n, +4 size
  parser.print(F("~Voltage Plot"));
  parser.button(submenu_Cmd); // start Button (opens sub-menu)
  parser.print(F("<bg n>")); // background n
  parser.print(F("~"));
  parser.print(submenu_var); // output the current text
  parser.endOfMsg();  // close pfod message. Send }
}

void pfodMainMenu::sendMainMenuUpdate(pfodParser& parser) {
  parser.menuUpdate();  // start an Update Menu pfod message. Send {;
  // send menu items that should be updated
  parser.onOffDisplay(sliderDisplay_Cmd); // start Data Display (outputs |!cmd)
  parser.print('`');
  parser.print(sliderDisplay_var); // output the current value
  parser.onOffDisplay(onOffIn_Cmd); // start On/Off Display (outputs |!cmd)
  parser.print('`');
  parser.print(onOffIn_var); // output the current state
  parser.slider(sliderIO_Cmd); // start Slider
  parser.print('`');
  parser.print(sliderIO_var); // output the current value 
  parser.slider(onOffOut_Cmd); // start Slider
  parser.print('`');
  parser.print(onOffOut_var); // output the current value 
  parser.endOfMsg();  // close pfod message. Send }
  // ============ end of menu ===========
}

void sliderDisplay_readADC() {
  if (sliderDisplay_adcTimer.justFinished()) {
    sliderDisplay_adcTimer.repeat(); // restart timer, without drift
    sliderDisplay_var = analogRead(sliderDisplay_pin);  // read ADC input
  }
}

static void onOffOut_Cmd_checkPulse() {
  if (onOffOut_Cmd_pulseRunning && ((millis() - onOffOut_Cmd_pulseStartTime) > onOffOut_Cmd_PULSE_LENGTH)) {
    onOffOut_Cmd_pulseRunning = false; // timer finished
    onOffOut_var = 0;  // return output to LOW
    digitalWrite(onOffOut_pin,onOffOut_var); // update output pin
  }
}

